/* 
 * Mirrors [`CoordAlgorithm`] across the FFI boundary.
 */

public enum FfiAlgorithm {
    /**
     * Weighted median relaxation with compaction (simpler, O(N·passes)).
     */
    case medianRelax
    /**
     * Brandes-Köpf alignment averaging (better quality, O(N)).
     */
    case brandesKopf
}

