/**
 * Everything that can go wrong calling `layout()` — either the input
 * graph was invalid, or the engine panicked internally (a bug, not bad
 * input; see the variant docs).
 */
public enum FfiLayoutError {
    /**
     * The input graph itself was invalid: a duplicate/unknown node id, or
     * (from `LayoutError`) a genuine cycle that survived cycle breaking.
     */
    case InvalidGraph(message: String)

    /**
     * The layout engine panicked internally. This is always a bug in the
     * engine, not bad input — please report it with the graph that
     * triggered it.
     */
    case Internal(message: String)
}

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiLayoutError: FfiConverterRustBuffer {
    typealias SwiftType = FfiLayoutError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiLayoutError {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        case 1: return try .InvalidGraph(
                message: FfiConverterString.read(from: &buf)
            )

        case 2: return try .Internal(
                message: FfiConverterString.read(from: &buf)
            )

        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiLayoutError, into buf: inout [UInt8]) {
        switch value {
        case .InvalidGraph(_ /* message is ignored*/ ):
            writeInt(&buf, Int32(1))
        case .Internal(_ /* message is ignored*/ ):
            writeInt(&buf, Int32(2))
        }
    }
}

