            FfiConverterTypeFfiPoint.write(start, into: &buf)
            FfiConverterTypeFfiPoint.write(control1, into: &buf)
            FfiConverterTypeFfiPoint.write(control2, into: &buf)
            FfiConverterTypeFfiPoint.write(end, into: &buf)
        }
